from pathlib import Pathimport numpy as npimport pandas as pdimport refrom typing import Uniondef load_lf_nmr(path):    """    Load all Oxford LF-NMR XML files from a folder (including subfolders).    Parameters    ----------    path : str or Path        Folder containing LF-NMR XML files.    Returns    -------    df : pandas.DataFrame        Rows = sample IDs        Columns = time (ms)        Values = signal magnitude    """    path = Path(path)    files = sorted(        path.rglob("*.xml"),        key=lambda f: (            str(f.parent),            [int(x) if x.isdigit() else x             for x in re.split(r"(\d+)", f.stem)]        )    )    spectra = {}    for file in files:        try:            text = file.read_text(errors="ignore")        except Exception:            continue        if "Seconds" not in text:            continue        lines = text.splitlines()        seconds, real, imag = [], [], []        current = None        for line in lines:            line = line.strip()            if 'Column Name="Seconds"' in line:                current = seconds                continue            if 'Column Name="Real"' in line:                current = real                continue            if 'Column Name="Imaginary"' in line:                current = imag                continue            m = re.search(r"<Value>(.*?)</Value>", line)            if m and current is not None:                current.append(float(m.group(1)))        if not (len(seconds) == len(real) == len(imag)):            continue        magnitude = np.sqrt(np.square(real) + np.square(imag))        spectra[file.stem] = magnitude    df = pd.DataFrame(spectra).T    df.columns = np.array(seconds) * 1000    df.columns.name = "time_ms"    df.index.name = "sample_id"    return dfdef save_hdf(df, path, key="data"):    """    Save a DataFrame as a compressed HDF5 file.    Parameters    ----------    df : pandas.DataFrame        DataFrame to save.    path : str or pathlib.Path        Output HDF5 file path.    key : str, default="data"        Name used to store the DataFrame inside the HDF5 file.    Returns    -------    pathlib.Path        Path of the saved HDF5 file.    Usage    -----    >>> save_hdf(df, "spectra.h5")    """    path = Path(path)    # Create the output directory if it does not exist    path.parent.mkdir(parents=True, exist_ok=True)    df.to_hdf(        path,        key=key,        mode="w",        format="fixed",        complevel=9,        complib="zlib",    )    return pathdef read_hdf(path, key="data"):    """    Read a DataFrame from an HDF5 file.    Parameters    ----------    path : str or pathlib.Path        HDF5 file path.    key : str, default="data"        Name of the DataFrame stored inside the HDF5 file.    Returns    -------    pandas.DataFrame        Loaded DataFrame.    Usage    -----    >>> df = read_hdf("spectra.h5")    """    path = Path(path)    if not path.exists():        raise FileNotFoundError(            f"HDF5 file was not found: {path}"        )    return pd.read_hdf(        path,        key=key,    )def list_hdf_keys(path):    """    List all datasets stored in an HDF5 file.    Parameters    ----------    path : str or pathlib.Path        Path to the HDF5 file.    Returns    -------    list of str        Dataset names stored in the HDF5 file.    Examples    --------    >>> list_hdf_keys("spectra.h5")    ['spectra', 'metadata']    """    path = Path(path)    if not path.exists():        raise FileNotFoundError(            f"HDF5 file was not found:\n{path}"        )    with pd.HDFStore(path, mode="r") as store:        return [k.lstrip("/") for k in store.keys()]"""Functions for reading and processing FTIR data."""def read_opus(    folder_path: Union[str, Path],    strict_axis: bool = True,    verbose: bool = True,) -> pd.DataFrame:    """    Read absorbance spectra from Bruker OPUS ``.0`` files.    Each file is read from the ``AB`` data block. Spectra are returned    with samples in rows and wavenumbers in columns.    Parameters    ----------    folder_path : str or pathlib.Path        Folder containing Bruker OPUS ``.0`` files.    strict_axis : bool, default=True        How to handle spectra with a wavenumber axis that differs from        the first successfully loaded spectrum.        If ``True``, files with a different axis are skipped.        If ``False``, spectra are interpolated onto the axis of the        first successfully loaded spectrum.    verbose : bool, default=True        Print information about loaded, skipped, interpolated, or        unreadable files.    Returns    -------    pandas.DataFrame        Spectral matrix with samples as rows and wavenumbers as columns.        Sample names are derived from file names without extensions.    Raises    ------    FileNotFoundError        If ``folder_path`` does not exist.    NotADirectoryError        If ``folder_path`` is not a directory.    ImportError        If ``brukeropusreader`` is not installed.    Notes    -----    Only the OPUS absorbance block ``AB`` is read.    When ``strict_axis=False``, interpolation is performed only within    the wavenumber range of the source spectrum. Values outside that    range are set to ``NaN``.    Examples    --------    >>> import foodomicspy as fp    >>> spectra = fp.ftir.read_opus("data/ftir")    >>> spectra.shape    (20, 1764)    """    try:        from brukeropusreader import read_file    except ImportError as exc:        raise ImportError(            "Reading OPUS files requires 'brukeropusreader'. "            "Install it with: pip install brukeropusreader"        ) from exc    folder = Path(folder_path).expanduser()    if not folder.exists():        raise FileNotFoundError(f"Folder not found: {folder}")    if not folder.is_dir():        raise NotADirectoryError(f"Expected a folder, received: {folder}")    files = sorted(        path        for path in folder.iterdir()        if path.is_file() and path.suffix.lower() == ".0"    )    if not files:        if verbose:            print(f"No OPUS .0 files found in: {folder}")        return pd.DataFrame()    spectra: dict[str, np.ndarray] = {}    reference_axis: np.ndarray | None = None    for file_path in files:        try:            opus_data = read_file(str(file_path))            if "AB" not in opus_data:                if verbose:                    print(f"Skipped {file_path.name}: no 'AB' block.")                continue            x = np.asarray(opus_data.get_range("AB"), dtype=float).squeeze()            y = np.asarray(opus_data["AB"], dtype=float).squeeze()            if x.ndim != 1 or y.ndim != 1:                raise ValueError(                    "The wavenumber axis and absorbance values must be one-dimensional."                )            if x.size != y.size:                raise ValueError(                    f"Axis and spectrum lengths differ: "                    f"{x.size} wavenumbers and {y.size} absorbance values."                )            if x.size < 2:                raise ValueError("The spectrum contains fewer than two data points.")            if not np.all(np.isfinite(x)):                raise ValueError("The wavenumber axis contains non-finite values.")            if reference_axis is None:                reference_axis = x.copy()            elif not np.allclose(                reference_axis,                x,                rtol=1e-7,                atol=1e-8,            ):                if strict_axis:                    if verbose:                        print(                            f"Skipped {file_path.name}: "                            "wavenumber axis differs from the reference axis."                        )                    continue                y = _interpolate_spectrum(                    source_axis=x,                    source_values=y,                    target_axis=reference_axis,                )                if verbose:                    print(                        f"Interpolated {file_path.name} "                        "onto the reference wavenumber axis."                    )            spectra[file_path.stem] = y            if verbose:                print(f"Loaded {file_path.name}")        except Exception as exc:            if verbose:                print(f"Could not read {file_path.name}: {exc}")    if not spectra or reference_axis is None:        return pd.DataFrame()    result = pd.DataFrame.from_dict(        spectra,        orient="index",        columns=reference_axis,    )    result.index.name = "sample"    result.columns.name = "wavenumber_cm-1"    return resultdef _interpolate_spectrum(    source_axis: np.ndarray,    source_values: np.ndarray,    target_axis: np.ndarray,) -> np.ndarray:    """    Interpolate a spectrum while supporting ascending or descending axes.    This is an internal helper function.    """    order = np.argsort(source_axis)    source_axis_sorted = source_axis[order]    source_values_sorted = source_values[order]    unique_axis, unique_indices = np.unique(        source_axis_sorted,        return_index=True,    )    unique_values = source_values_sorted[unique_indices]    interpolated = np.interp(        target_axis,        unique_axis,        unique_values,        left=np.nan,        right=np.nan,    )    return interpolated